const boldDesigns={
editorial:{name:'Editorial',label:'Paper / vermilion',description:'Oversized serif headlines, quiet rules, and a single vivid accent. Policy reads like a document.',colors:['#f6f3eb','#f6f3eb','#25251f','#b63520','#eae5d9','#68675e','#d3cec1'],dark:false},
electric:{name:'Electric',label:'Chalk / cobalt',description:'Graphic blue fields, compact sans-serif type, and crisp square edges. A more direct operating surface.',colors:['#f0f2f6','#ffffff','#17233c','#1947db','#e2e9ff','#57647b','#ccd4e3'],dark:false},
nocturne:{name:'Nocturne',label:'Carbon / citron',description:'Deep charcoal, luminous accents, and generous spacing. A focused environment for policy and service health.',colors:['#171915','#20231c','#edf0e5','#d0ef67','#303728','#b0b8a5','#404737'],dark:true}
};
Object.assign(paletteOptions,boldDesigns);
let boldSelection=localStorage.getItem('ipe-bold-design')||'editorial';if(!boldDesigns[boldSelection])boldSelection='editorial';
function boldNavigation(){const section=['policies','contracts'].includes(current.screen)?'policies':['map','fleet','integrations'].includes(current.screen)?'map':current.screen;return `<header class="bold-header"><a href="#workspace/overview" class="brand" aria-label="IPE overview"><span class="brandmark">//</span>ipe<span class="bold-wordmark">POLICY WORKSPACE</span></a><nav aria-label="Main navigation">${[['overview','Overview'],['policies','Policies'],['map','Services'],['observability','Telemetry'],['rollouts','Rollouts']].map(([key,label])=>`<a href="#workspace/${key}" ${section===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><span class="bold-scope"><i></i>Northstar / Production</span></header>`}
function boldSubnav(){const group=['policies','contracts'].includes(current.screen)?[['policies','Executable policies'],['contracts','External contracts']]:['map','fleet','integrations'].includes(current.screen)?[['map','Service map'],['fleet','Endpoints'],['integrations','Integrations']]:[];return group.length?`<nav class="bold-subnav" aria-label="Section navigation">${group.map(([id,label])=>`<a href="#workspace/${id}" ${current.screen===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`:''}
function boldOverview(){return `<section class="bold-hero"><div class="bold-intro"><div class="kicker">YOUR POLICY WORKSPACE</div><h1>Clear policy.<br>Confident operations.</h1><p>Define what runs. Understand what depends on it.</p><a class="btn primary" href="#workspace/policies">Open policy library ${icon('arrow')}</a></div><div class="bold-numbers"><a href="#workspace/policies"><strong>${policies.length.toString().padStart(2,'0')}</strong><span>Executable policies ${icon('arrow')}</span></a><a href="#workspace/contracts"><strong>03</strong><span>External contracts ${icon('arrow')}</span></a><a href="#workspace/map"><strong>04</strong><span>Registered endpoints ${icon('arrow')}</span></a></div></section><a class="bold-alert" href="#workspace/rollouts"><span class="alert-index">${assigned?'✓':'01'}</span><span><strong>${assigned?'Rollout complete.':'One endpoint is behind.'}</strong> ${assigned?'All three enforcers report r17.':'east-03 is running r16. Revision r17 is waiting.'}</span><span class="alert-action">${assigned?'View rollout':'Review rollout'} ${icon('arrow')}</span></a><div class="bold-content"><section><div class="bold-section-head"><h2>Policy in practice</h2><a href="#workspace/policies">All policies ${icon('arrow')}</a></div>${policies.slice(0,3).map((p,i)=>`<button class="bold-policy" data-action="policy" data-id="${p.id}"><span class="bold-index">0${i+1}</span><span><strong>${esc(p.name)}</strong><small>${p.scope} · ${p.rev}</small></span>${badge(p.status)}${icon('arrow')}</button>`).join('')}</section><section class="bold-context"><div class="bold-section-head"><h2>Source knowledge</h2><a href="#workspace/contracts">View all ${icon('arrow')}</a></div><button class="bold-source" data-action="contract" data-id="closure"><span class="kicker">SERVICENOW</span><h3>One condition<br>still needs context.</h3><p>Change closure has an unmodeled scripted requirement.</p><span class="source-action">Review coverage gap ${icon('arrow')}</span></button><a class="bold-map-link" href="#workspace/map">Explore the service map ${icon('arrow')}</a></section></div>`}
function boldMap(){return `${head('The service map.','Sources, policies, and the endpoints that enforce them.')}<div class="bold-map-summary"><span>${badge(assigned?'All current':'1 endpoint behind')}<span>4 registered endpoints · 2 source connections</span></span><button class="btn quiet" data-action="endpoint" data-id="integration-01">Integration runtime ${icon('arrow')}</button></div><div class="bold-map-canvas">${topology()}</div><div class="bold-map-footer"><span>Select a node to inspect ownership, grants, or active revisions.</span><a href="#workspace/observability">View telemetry ${icon('arrow')}</a></div>`}
function renderBoldWorkspace(){paletteSelection=boldSelection;const content=current.screen==='overview'?boldOverview():current.screen==='map'?boldMap():({policies:policiesScreen,contracts:contractsScreen,integrations:integrationsScreen,fleet:fleetScreen,observability:observabilityScreen,rollouts:rolloutsScreen}[current.screen])();$('#app').innerHTML=`<div class="review-shell workspace bold-workspace design-${boldSelection}">${boldNavigation()}<main class="bold-main">${boldSubnav()}${content}</main><footer class="bold-footer"><span>IPE / Design prototype · Sample data</span><div><button data-action="feedback">Feedback</button><button data-design-explore>Explore designs <span>${boldDesigns[boldSelection].name}</span> ${icon('down')}</button></div></footer></div>`;applyPalette();document.title=`${boldDesigns[boldSelection].name} · Policy Workspace · IPE`}
function exploreBold(){modal('Three stronger directions','Same policy workspace. A different visual point of view.',`<div class="bold-design-choices">${Object.entries(boldDesigns).map(([id,d])=>`<button data-bold-choice="${id}" class="bold-design-card" aria-pressed="${id===boldSelection}" style="--sample-bg:${d.colors[0]};--sample-text:${d.colors[2]};--sample-accent:${d.colors[3]}"><div class="design-sample ${id}"><span>IPE / ${id.toUpperCase()}</span><strong>Policy,<br>with purpose.</strong><i></i></div><div class="design-caption"><strong>${d.name} ${id===boldSelection?'✓':''}</strong><small>${d.label}</small><p>${d.description}</p></div></button>`).join('')}</div>`,`<a class="btn quiet" href="#review">Earlier concepts</a>${btn('Done','close','primary')}`);applyPalette()}
document.addEventListener('click',e=>{if(e.target.closest('[data-design-explore]'))exploreBold();const b=e.target.closest('[data-bold-choice]');if(!b)return;boldSelection=b.dataset.boldChoice;localStorage.setItem('ipe-bold-design',boldSelection);reviews.workspace={...reviews.workspace,design:boldSelection,designName:boldDesigns[boldSelection].name};persist();close();render();toast(boldDesigns[boldSelection].name+' applied.');});
